Java.Iterative:
public int jumpSearch(int[] arr, int target) {
    int step = (int) Math.sqrt(arr.length);
    int prev = 0;
    while (prev < arr.length && arr[Math.min(step, arr.length) - 1] < target) {
        prev = step;
        step += (int) Math.sqrt(arr.length);
        if (prev >= arr.length) {
            return -1;
        }
    }
    while (prev < Math.min(step, arr.length)) {
        if (arr[prev] == target) {
            return prev;
        }
        prev++;
    }
    return -1;
}

