Java.Recursion:
public int jumpSearchRecursive(int[] arr, int target, int start, int step) {
    int end = Math.min(step, arr.length);
    if (start >= arr.length) {
        return -1;
    }
    if (arr[end - 1] >= target) {
        return scanBlock(arr, target, start, end);
    }
    return jumpSearchRecursive(arr, target, end, end + (int) Math.sqrt(arr.length));
}

private int scanBlock(int[] arr, int target, int index, int end) {
    if (index >= end) {
        return -1;
    }
    if (arr[index] == target) {
        return index;
    }
    return scanBlock(arr, target, index + 1, end);
}
